import random
from itertools import combinations

def bfs_dist(adj, s, t, limit):
    # returns shortest distance from s to t up to limit
    dist = {s: 0}
    frontier = [s]
    for d in range(limit):
        new_frontier = []
        for u in frontier:
            for w in adj[u]:
                if w not in dist:
                    dist[w] = d+1
                    if w == t:
                        return d+1
                    new_frontier.append(w)
        frontier = new_frontier
    return None  # > limit

def try_build(n=19, target=32, seed=0, girth=7):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = []
    # order pairs randomly
    pairs = list(combinations(range(n), 2))
    random.shuffle(pairs)
    for u,v in pairs:
        # check adding edge creates cycle of length < girth
        # i.e., current distance u-v in graph is < girth-1
        d = bfs_dist(adj, u, v, girth-2)
        if d is None:
            adj[u].add(v); adj[v].add(u)
            edges.append((u,v))
    return edges, adj

best = 0
for s in range(200):
    e, adj = try_build(seed=s)
    if len(e) > best:
        best = len(e)
        best_e = e
        best_s = s
print("best edges:", best, "seed:", best_s)

