from itertools import combinations, permutations
from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

n = 19
pool = IDPool()
def E(u,v):
    if u>v: u,v=v,u
    return pool.id(('e',u,v))
def C(v,c):
    return pool.id(('c',v,c))

clauses = []
for v in range(n):
    clauses.append([C(v,0),C(v,1),C(v,2)])
    for c1,c2 in combinations(range(3),2):
        clauses.append([-C(v,c1),-C(v,c2)])
for u,v in combinations(range(n),2):
    for c in range(3):
        clauses.append([-E(u,v), -C(u,c), -C(v,c)])

for L in range(3,7):
    seen = set()
    for verts in combinations(range(n), L):
        vmin = verts[0]
        rest = verts[1:]
        for perm in permutations(rest):
            seq = (vmin,) + perm
            rev = (seq[0],) + seq[:0:-1]
            key = min(seq, rev)
            if key in seen: continue
            seen.add(key)
            cl = []
            for i in range(L):
                a,b = seq[i], seq[(i+1)%L]
                cl.append(-E(a,b))
            clauses.append(cl)

edge_vars = [E(u,v) for u,v in combinations(range(n),2)]
card = CardEnc.atleast(lits=edge_vars, bound=32, vpool=pool, encoding=EncType.seqcounter)
clauses.extend(card.clauses)

solver = Glucose4()
for cl in clauses:
    solver.add_clause(cl)
print("solving...")
import time
t=time.time()
res = solver.solve()
print("result:", res, "time:", time.time()-t)

if res:
    model = solver.get_model()
