import random
from itertools import combinations

def has_short_cycle_via_edge(adj, u, v, girth):
    # BFS from u, skipping edge u-v if exists, check distance to v < girth-1
    # But we're adding edge, so we want current dist(u,v) in graph without this edge
    # If dist < girth-1, adding creates cycle < girth
    dist = {u:0}
    frontier=[u]
    for d in range(girth-2):
        nf=[]
        for x in frontier:
            for y in adj[x]:
                if y not in dist:
                    dist[y]=d+1
                    if y==v: return True
                    nf.append(y)
        frontier=nf
    return False

def build_random(n, girth, seed):
    random.seed(seed)
    adj=[set() for _ in range(n)]
    edges=[]
    pairs=list(combinations(range(n),2))
    random.shuffle(pairs)
    for u,v in pairs:
        if not has_short_cycle_via_edge(adj,u,v,girth):
            adj[u].add(v); adj[v].add(u); edges.append((u,v))
    return edges,adj

def is_3colorable(n, edges):
    # brute force with backtracking
    adj=[[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    col=[-1]*n
    order = sorted(range(n), key=lambda x:-len(adj[x]))
    def bt(i):
        if i==n: return True
        v=order[i]
        used=set(col[w] for w in adj[v] if col[w]!=-1)
        for c in range(3):
            if c not in used:
                col[v]=c
                if bt(i+1): return True
                col[v]=-1
        return False
    if bt(0):
        return col
    return None

